              <button type="button" data-action="roughcut-queue-select" data-id="${escapeHtml2(item.id)}"${item.id === context.assetId() ? ' aria-current="true"' : ""} title="${escapeHtml2(item.sourcePath || item.name)}"><strong>${escapeHtml2(item.name)}</strong><span>${kept ? `${kept} 段已保留` : "待标记"}${context.available(item.id) ? "" : " · 素材未连接"}</span></button>
